            counts[v] = counts.get(v, 0) + 1
    background = max(counts.keys(), key=lambda k: counts[k])

    G = [[input_grid[r][c] for c in range(w)] for r in range(h)]

    visited = set()
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] != background and (r,c) not in visited:
                comp = []
                stack = [(r,c)]

                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
